    {profile : Agent → Valuation Item K} {goods : Finset Item}
    {allocation : Allocation Agent Item}
    (hEF : EnvyFree profile goods allocation), EnvyFreeUpToOneGood profile goods allocation

: ∀ [DecidableEq Agent] [DecidableEq Item]
    {profile : Agent → Valuation Item K} {goods : Finset Item}
    {order : List Agent} {allocation : Allocation Agent Item}
    {picks : List (Agent × Item)}
    (hlog : PickLogRoundRobin profile goods order picks)
    (hmatch : PickLogMatchesAllocation allocation picks)
    (i : Agent), (picks.filterMap
        (fun p : Agent × Item => if p.1 = i then some p.2 else none)).toFinset =
      bundle goods allocation i

: ∀ [DecidableEq Agent] [DecidableEq Item]
    {profile : Agent → Valuation Item K} {goods : Finset Item}
    {allocation : Allocation Agent Item} {i j : Agent}
    {iPicks jPicks : List Item}
    (hdom : SequentiallyDominates (profile i) iPicks jPicks)
    (hiPicks : iPicks.toFinset = bundle goods allocation i)
    (hjPicks : jPicks.toFinset = bundle goods allocation j), DoesNotEnvyUpToOneGood profile goods allocation i j

: ∀ [DecidableEq Agent] [DecidableEq Item]
    {profile : Agent → Valuation Item K} {goods : Finset Item}
    {order : List Agent} {allocation : Allocation Agent Item}
    {picks : List (Agent × Item)}
    (hlog : PickLogRoundRobin profile goods order picks)
    (hmatch : PickLogMatchesAllocation allocation picks)
    (a : Agent), ((picks.filter fun p => p.1 = a).map Prod.snd).toFinset =
      bundle goods allocation a

: ∀ [DecidableEq Item] {jPicks : List Item}
    (hnd : jPicks.Nodup) (hnonempty : 0 < jPicks.length), jPicks.toFinset.erase (jPicks.get ⟨0, hnonempty⟩) =
      jPicks.tail.toFinset

: ∀ [DecidableEq Item]
    (v : Valuation Item K) {iPicks jPicks : List Item}
    (hdom : SequentiallyDominates v iPicks jPicks), bundleValue v jPicks.tail.toFinset ≤ bundleValue v iPicks.toFinset

[DecidableEq Item] {s : Finset Item} {l : List Item}
    (h : l.toFinset = s) (hlen : 0 < l.length) :
    l.get ⟨0, hlen⟩ ∈ s

: ∀ [DecidableEq Item]
    (v : Valuation Item K) {s t : Finset Item} {g : Item}
    (hg : g ∈ s) (hbound : bundleValue v s ≤ bundleValue v t), bundleValue v (s.erase g) ≤ bundleValue v t
